#include <print>

class Score {
public:
    Score(int total) : total_(total), done_(0) {}
    int remaining() const {
        done_ = 0;
        return total_ - done_;
    }
    double progress() const { return static_cast<double>(done_) / total_; }
    void add(int n) { done_ += n; }
private:
    int total_, done_;
};

void report(const Score& s) {
    std::println("还剩 {} 个", s.remaining());
}

int main() {
    Score s(10);
    s.add(4);
    report(s);
    return 0;
}
// 报错原话：assignment of member Score::done_ in read-only object，删掉那一行才过

