#include <print>

class Score {
public:
    const int remaining() const { return total_; }
    void add(int n) { done_ = n; }
private:
    int total_ = 10;
    int done_ = 0;
};

int main() {
    Score s;
    std::println("{}", s.remaining());
    return 0;
}

